components.css:
.ds-btn-primary {
  background: #0f172a;
  color: #fefcf6;
  font-family: 'Cormorant Garamond', Georgia, 'Times New Roman', serif;
  font-size: 0.875rem;
  font-weight: 500;
  font-style: italic;
  letter-spacing: 0.025em;
  padding: 0.625rem 1.5rem;
  border: none;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: background-color 0.2s ease;
}
.ds-btn-primary:hover {
  background: #1e253c;
}
.ds-btn-primary:focus-visible {
  outline: 2px solid #b8932e;
  outline-offset: 2px;
}
.ds-btn-primary:active {
  background: #060b18;
}
.ds-btn-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.ds-btn-ghost {
  background: transparent;
  color: #475685;
  font-family: 'Cormorant Garamond', Georgia, 'Times New Roman', serif;
  font-size: 0.875rem;
  font-weight: 500;
  font-style: italic;
  letter-spacing: 0.025em;
  padding: 0.625rem 1.25rem;
  border: 1px solid #8797be;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: border-color 0.2s ease, color 0.2s ease;
}
.ds-btn-ghost:hover {
  border-color: #475685;
  color: #1e253c;
}
.ds-btn-ghost:focus-visible {
  outline: 2px solid #b8932e;
  outline-offset: 2px;
}
.ds-btn-ghost:active {
  background: #eff1f7;
}

.ds-btn-destructive {
  background: transparent;
  color: #722f37;
  font-family: 'Cormorant Garamond', Georgia, 'Times New Roman', serif;
  font-size: 0.75rem;
  font-weight: 500;
  font-style: italic;
  letter-spacing: 0.025em;
  padding: 0.375rem 0.75rem;
  border: 1px solid #cfa5b0;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: border-color 0.2s ease, color 0.2s ease;
}
.ds-btn-destructive:hover {
  border-color: #722f37;
  color: #5c282f;
}
.ds-btn-destructive:focus-visible {
  outline: 2px solid #b8932e;
  outline-offset: 2px;
}
.ds-btn-destructive:active {
  background: #f3e8eb;
}

.ds-input {
  width: 100%;
  background: #fefcf6;
  color: #0f172a;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 0.875rem;
  padding: 0.5rem 0.75rem;
  border: 1px solid #dee2ee;
  border-radius: 0.5rem;
  outline: none;
  transition: border-color 0.15s ease;
}
.ds-input::placeholder {
  color: #8797be;
  font-style: italic;
}
.ds-input:focus {
  border-color: #475685;
  box-shadow: 0 0 0 1px #b6c0d9;
}

.ds-sidebar {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 15rem;
  background: #0f172a;
  border-right: 1px solid #2a3250;
  display: flex;
  flex-direction: column;
  padding: 1.5rem 0.75rem;
}
.ds-nav-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.625rem 0.75rem;
  margin-bottom: 0.125rem;
  color: #dee2ee;
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 0.875rem;
  font-weight: 500;
  font-style: italic;
  letter-spacing: 0.025em;
  text-decoration: none;
  border-left: 2px solid transparent;
  border-radius: 0.5rem;
  transition: background-color 0.15s ease, color 0.15s ease;
}
.ds-nav-item:hover {
  background: #1e253c;
  color: #fef7ed;
}
.ds-nav-item.active {
  background: rgba(122, 93, 34, 0.15);
  border-left-color: #b8932e;
  color: #fef7ed;
}
.ds-nav-icon {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
}

.ds-card {
  background: #ffffff;
  border: 1px solid #dee2ee;
  border-radius: 0.75rem;
  padding: 1.25rem;
}
.ds-card-title {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 0.875rem;
  font-weight: 600;
  font-style: italic;
  color: #36406a;
  margin: 0 0 0.75rem;
}
.ds-card-body {
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 0.875rem;
  line-height: 1.6;
  color: #1e253c;
  margin: 0;
}

.ds-card-parchment {
  background: #fef7ed;
  border: 1px solid #dee2ee;
  border-radius: 0.75rem;
  padding: 1rem 1.25rem;
}
.ds-card-parchment .ds-card-body {
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 0.875rem;
  line-height: 1.6;
  color: #1e253c;
  margin: 0;
}

.ds-tabs {
  display: flex;
  gap: 0.25rem;
  padding: 0.25rem;
  background: #ffffff;
  border: 1px solid #dee2ee;
  border-radius: 0.75rem;
}
.ds-tab {
  flex: 1;
  padding: 0.5rem 1rem;
  background: transparent;
  color: #475685;
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 0.875rem;
  font-weight: 500;
  font-style: italic;
  letter-spacing: 0.025em;
  border: none;
  border-radius: 0.5rem;
  cursor: pointer;
  transition: background-color 0.15s ease, color 0.15s ease;
}
.ds-tab:hover {
  color: #1e253c;
}
.ds-tab:focus-visible {
  outline: 2px solid #b8932e;
  outline-offset: 2px;
}
.ds-tab.active {
  background: #0f172a;
  color: #fef7ed;
}

.ds-chat {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.ds-chat-bubble {
  max-width: 85%;
  padding: 0.875rem 1.25rem;
  font-family: Georgia, 'Times New Roman', serif;
  font-size: 0.875rem;
  line-height: 1.6;
  white-space: pre-wrap;
  border-radius: 1rem;
}
.ds-chat-user {
  align-self: flex-end;
  background: #0f172a;
  color: #fef7ed;
}
.ds-chat-assistant {
  align-self: flex-start;
  background: #fef7ed;
  color: #1e253c;
  border: 1px solid #dee2ee;
}

.ds-status-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.75rem;
  padding: 2.5rem 1rem;
}
.ds-spinner {
  width: 1.25rem;
  height: 1.25rem;
  color: #b8932e;
  animation: ds-spin 0.8s linear infinite;
}
@keyframes ds-spin {
  to { transform: rotate(360deg); }
}
.ds-status-text {
  font-family: 'Cormorant Garamond', Georgia, serif;
  font-size: 0.875rem;
  font-style: italic;
  color: #475685;
}
